import sys

def parse_grid(text):
    lines = [l.strip() for l in text.strip().split('\n') if l.strip()]
    grid = []
    for line in lines:
        if ': ' in line:
            line = line.split(': ', 1)[1]
        grid.append(line.strip())
    return grid

def find_positions(grid, char):
    positions = []
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == char:
                positions.append((r, c))
    return positions

def get_crate_bbox(positions):
    if not positions:
        return None
    rows = [p[0] for p in positions]
    cols = [p[1] for p in positions]
    return (min(rows), max(rows), min(cols), max(cols))

# Read two grids from separate files
import json
if len(sys.argv) >= 3:
    with open(sys.argv[1]) as f:
        grid1 = parse_grid(f.read())
    with open(sys.argv[2]) as f:
        grid2 = parse_grid(f.read())

    c1 = find_positions(grid1, 'c')
    c2 = find_positions(grid2, 'c')

    b1 = get_crate_bbox(c1)
    b2 = get_crate_bbox(c2)

    print(f"Grid1 crate: {b1}, count={len(c1)}")
    print(f"Grid2 crate: {b2}, count={len(c2)}")

    if b1 != b2:
        dr = b2[0] - b1[0]
        dc = b2[2] - b1[2]
        print(f"Crate moved: dr={dr}, dc={dc}")
    else:
        print("Crate did not move")
else:
    print("Usage: python track_crate.py <grid1_file> <grid2_file>")
